 if(!authReady||!dataReady)return <div className="auth-screen"><ThemeToggle theme={theme} onToggle={toggleTheme}/><div className="auth-card"><img className="brand-logo auth-logo" src={logoControlGastos} alt="Logo Control Gastos"/><strong>Preparando tus finanzas…</strong></div></div>;
 if(!user)return <><div className="auth-screen"><ThemeToggle theme={theme} onToggle={toggleTheme}/><div className="auth-card"><img className="brand-logo auth-logo" src={logoControlGastos} alt="Logo Control Gastos"/><span className="auth-eyebrow">FINANZAS PERSONALES</span><h1>Tus cuentas, en orden.</h1><p>Iniciá sesión para guardar tus tarjetas, gastos y servicios en tu cuenta.</p><a className="google-login" href="/api/auth/google/start"><GoogleMark/> Continuar con Google <ArrowRight/></a><small>Tu información queda privada y asociada a tu usuario.</small></div></div><ToastViewport items={toasts} onDismiss={id=>setToasts(items=>items.filter(item=>item.id!==id))}/></>;
